-- pos-warranty: Flyway baseline (flattened 2026-09-09 from the previous migration history) with the
-- ADR-0062 tenancy schema folded in. Generated by scripts/db/tenancy/flatten.py from a pg_dump of a
-- database migrated with the retired scripts; the tenancy additions are mechanical and are listed in
-- docs/TENANCY_SCHEMA.md. Global (unscoped) tables: src/main/resources/db/tenancy-global-tables.txt.
--
-- Tenant context: app_current_tenant() reads the session setting app.current_tenant, which the
-- TenantAwareDataSource (pos-tenancy-common, plan WS1) binds per checkout. Until then the owner role
-- carries a transitional default (postgres/init-tenancy.sh) and tests set it per connection.
-- With nothing bound: NULL -> every scoped table reads as empty and refuses inserts (fail closed).

-- Functions are emitted before the tables they reference (pg_dump order); do not validate bodies.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public.app_current_tenant() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$ SELECT NULLIF(current_setting('app.current_tenant', true), '')::uuid $$;

CREATE TABLE public.claim_code_sequence (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    code_year integer NOT NULL,
    next_seq bigint NOT NULL
);

CREATE TABLE public.claim_note (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    claim_id uuid NOT NULL,
    note text NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    created_by character varying(255)
);

CREATE TABLE public.claim_settlement (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    claim_id uuid NOT NULL,
    settlement_type character varying(32) NOT NULL,
    status character varying(32) NOT NULL,
    replacement_workorder_id uuid,
    invoice_id uuid,
    invoice_adjustment_id uuid,
    refund_record_id uuid,
    covered_amount numeric(19,4),
    customer_amount numeric(19,4),
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    created_by character varying(255),
    updated_by character varying(255)
);

CREATE TABLE public.claim_status_history (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    claim_id uuid NOT NULL,
    from_status character varying(32),
    to_status character varying(32) NOT NULL,
    actor character varying(255),
    reason text,
    created_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.event_outbox (
    id uuid NOT NULL,
    topic character varying(255) NOT NULL,
    record_key character varying(255) NOT NULL,
    payload text NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    published_at timestamp(6) with time zone,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text
);

CREATE TABLE public.ext_catalog (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    product_id uuid NOT NULL,
    sku character varying(128),
    name character varying(512),
    manufacturer_id uuid,
    manufacturer_name character varying(255),
    manufacturer_brand character varying(255),
    category_id uuid,
    category character varying(255),
    warranty character varying(2048),
    manufacturer_warranty character varying(2048),
    active boolean DEFAULT true NOT NULL,
    aggregate_version bigint NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.ext_invoice (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    invoice_id uuid NOT NULL,
    invoice_number character varying(64),
    party_id character varying(64),
    status character varying(64),
    invoice_created_at timestamp(6) with time zone,
    aggregate_version bigint NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.ext_invoice_line (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    invoice_item_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    description character varying(512),
    quantity numeric(19,4),
    unit_price numeric(19,4),
    amount numeric(19,4),
    workorder_item_id uuid,
    item_type character varying(32)
);

CREATE TABLE public.ext_location (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    location_id uuid NOT NULL,
    name character varying(255),
    active boolean DEFAULT true NOT NULL,
    aggregate_version bigint NOT NULL,
    financial_ancestor_ids text DEFAULT ''::text NOT NULL,
    other_ancestor_ids text DEFAULT ''::text NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.ext_location_parent (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    child_id uuid NOT NULL,
    parent_type character varying(64) NOT NULL,
    parent_id uuid NOT NULL
);

CREATE TABLE public.ext_vehicle (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
